-- DWA-M-820-2 · engineer hints on every field, equation and compliance requirement (hint wave 2026-10-06).
-- Each description now carries a German hint and an English part after the marker "[EN] " (src/lib/eval/hint-text.ts; the form
-- renders the part of the page locale; the approval refusal prints the whole text as "Hinweis" for a block gate without its inputs).
-- Content authored from the printed guideline pages (rendered PDF read in the authoring session; the authoring JSON in the vault
-- carries a source string with the printed page per hint); every number / limit / clause in a hint is traceable to those pages.
-- SAFETY: text only (fields.description, equations.description, compliance_requirements.description); no field, equation, gate,
-- value or severity changes. The pre-block descriptions (encoder notes) are restored by the rollback and kept in the inventory JSON.
-- STAGED — not applied. Apply: node scripts/apply-migration.mjs scripts/migrations/20261006222000_m820_2_hints.sql
-- Rollback: scripts/migrations/rollback-20261006222000_m820_2_hints.sql
BEGIN;
UPDATE fields x SET description = 'Rechtlicher Name des Auftraggebers (Bauherr), wie in §2.1 definiert. Erscheint als Kopfzeile in allen Arbeitsblättern dieses Projekts - reine Identifikation, keine eigene Mindestanforderung.
[EN] Legal name of the Auftraggeber (Bauherr), as defined in §2.1. Shown as the header on every worksheet of the project - a project identifier, not a value with its own requirement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'client_name';
UPDATE fields x SET description = 'Klassifiziert den Auftraggeber als Kommune, Versorger, Privat oder Sonstige. Das Merkblatt kennt keine solche Typisierung; die Angabe dient der Projektbeschreibung und steuert keine Prüfung.
[EN] Classifies the client as municipality, utility, private or other. The guideline prints no such typology; the entry describes the project and drives no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'client_type';
UPDATE fields x SET description = 'Niedrig/Mittel/Hoch - Einschätzung der Projektkomplexität. Nach §4.3.5 richten sich Inhalt und Umfang des Projekthandbuchs nach der Komplexität des Projekts und sind auf das Notwendige beschränkt; nach §5.3.4 orientieren sich die Planungszeiträume an der Komplexität der Maßnahme.
[EN] Low/Medium/High - assessment of project complexity. Per §4.3.5 the handbook''s content and scope follow the project''s complexity and are limited to what is necessary; per §5.3.4 planning periods follow the complexity of the measure.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'complexity_level';
UPDATE fields x SET description = 'Mehrfachauswahl der beauftragten HOAI-Leistungsphasen LPH 0-9. §1 legt den Anwendungsbereich des Merkblatts genau auf diese Spanne fest, von der Bedarfsplanung (LPH 0) bis zur Objektbetreuung (LPH 9).
[EN] Multi-select of the commissioned HOAI phases LPH 0-9. §1 fixes the guideline''s own scope to exactly this span, from needs planning (LPH 0) to object support (LPH 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'included_hoai_phases';
UPDATE fields x SET description = 'Hauptbereich des Projekts. Nach §1 beziehen sich die Empfehlungen des Merkblatts im Wesentlichen auf Projekte der Wasserwirtschaft, des Wasserbaus, des Abwassers und des Abfalls.
[EN] Project''s primary sector. Per §1 the guideline''s recommendations relate essentially to projects in water management, hydraulic engineering, wastewater and waste.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'primary_sector';
UPDATE fields x SET description = 'Projektkategorie (Neubau, Sanierung, Erweiterung, Optimierung, Konzept). §1 unterscheidet nur "Konzepterstellung" und "Projektabwicklung"; die feinere Einteilung ist eine Werkzeugkategorie ohne eigene gedruckte Definition.
[EN] Project category (new build, rehabilitation, extension, optimisation, concept). §1 only distinguishes "concept work" from "project execution"; the finer breakdown is a tool category with no printed definition of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_category';
UPDATE fields x SET description = 'Freitext zur Verortung des Projekts (Gemeinde, Landkreis, Bundesland). Reine Projektangabe ohne eigene gedruckte Anforderung.
[EN] Free text locating the project (municipality, district, state). A plain project detail with no printed requirement of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_location';
UPDATE fields x SET description = 'Vollständiger Projektname, wie in Verträgen und Schriftverkehr verwendet. Dient als Kopfzeile aller Arbeitsblätter.
[EN] Full project name as used in contracts and correspondence. Feeds the header of every worksheet.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_name';
UPDATE fields x SET description = 'Kurzbezeichnung für Kopfzeilen und interne Ablage, optional.
[EN] Short identifier for headers and internal filing, optional.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_name_short';
UPDATE fields x SET description = 'Vom Auftraggeber vergebene eindeutige Projektnummer zur Zuordnung in Verträgen, Rechnungen und Berichten.
[EN] Unique project number assigned by the client, used to match contracts, invoices and reports.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_number';
UPDATE fields x SET description = 'Klein/Mittel/Groß. §4.1 stellt klar, dass die Anforderungen an wirksames Projektmanagement "abhängig von der Projektgröße und der Projektart" unterschiedlich sind und mit unterschiedlich vielen Ressourcen zu belegen sind.
[EN] Small/Medium/Large. §4.1 states that requirements for effective project management differ "depending on project size and project type" and must be resourced accordingly.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'project_size';
UPDATE fields x SET description = 'Freitext für explizite Ausschlüsse aus dem technischen Umfang, um spätere Umfangsstreitigkeiten zu vermeiden. Keine eigene gedruckte Mindestanforderung.
[EN] Free text recording explicit scope exclusions, to pre-empt later scope disputes. No printed requirement of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'scope_excluded';
UPDATE fields x SET description = 'Freitextbeschreibung der technischen Umfangsgrenzen des Projekts, gerahmt durch den Anwendungsbereich aus §1.
[EN] Free-text description of the project''s technical scope boundaries, framed by the §1 scope definition.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'scope_technical';
UPDATE fields x SET description = 'Lebenszyklus-Status dieses Arbeitsblatts (Entwurf bis Final). Reine Werkzeugsteuerung, kein Begriff des Merkblatts.
[EN] Lifecycle state of this worksheet (draft to final). Pure tool state, not a term the guideline defines.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'worksheet_status';
UPDATE fields x SET description = 'Wer die Bedarfsplanung (LPH 0) erbringt - Auftragnehmer, Auftraggeber selbst oder Dritter. §1 ordnet die Bedarfsplanung jedem Konzept und jedem Projekt zu ("von der Bedarfsplanung (LPH 0) bis zur Objektbetreuung (LPH 9)"); daher gibt es keine Option "entfällt".
[EN] Who performs needs planning (LPH 0) - contractor, client, or a third party. §1 assigns needs planning to every concept and every project ("from needs planning (LPH 0) to object support (LPH 9)"); there is therefore no "does not occur" option.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'verantwortung_lph0';
UPDATE fields x SET description = 'Wer die Bauüberwachung/Bauoberleitung (LPH 8) erbringt. §4.1 (S. 20): diese Leistungen "werden vergeben oder durch den Auftraggeber erbracht". Außer bei "Entfällt" gelten REQ-19 (820-2-09) und REQ-43 (820-2-20), auch bei Eigenleistung (§5.6.2, S. 52); REQ-44 nur bei Auftragnehmer oder Dritter. "Entfällt" nur ohne Bauausführung (reine Konzepterstellung); dann sind die LPH-8-Angaben ausgeblendet.
[EN] Who performs site supervision (LPH 8). §4.1 (p. 20): these services "are awarded or performed by the client". Unless "Does not occur", REQ-19 (820-2-09) and REQ-43 (820-2-20) apply, also when the client supervises himself (§5.6.2, p. 52); REQ-44 only for a contractor or third party. "Does not occur" only without construction (concept work only); the LPH 8 entries are then hidden.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'verantwortung_lph8';
UPDATE fields x SET description = 'Wer für die Objektbetreuung/Gewährleistung (LPH 9) verantwortlich ist - Auftragnehmer, Auftraggeber selbst oder Dritter. §5.8.3: "Es ist festgelegt, wer für die Phase LPH 9 verantwortlich ist." Außer bei "Entfällt" gelten REQ-51, REQ-52 und REQ-52-2 (820-2-24) für jeden Verantwortlichen. "Entfällt" nur ohne Bauausführung; dann sind die Gewährleistungsangaben ausgeblendet.
[EN] Who is responsible for object support / warranty (LPH 9) - contractor, client or third party. §5.8.3: "it is laid down who is responsible for phase LPH 9." Unless "Does not occur", REQ-51, REQ-52 and REQ-52-2 (820-2-24) apply whoever is responsible. "Does not occur" only without construction; the warranty entries are then hidden.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.symbol = 'verantwortung_lph9';
UPDATE compliance_requirements x SET description = 'Sperrt die Freigabe, bis Hauptbereich (primary_sector) und mindestens eine beauftragte Leistungsphase (included_hoai_phases) gesetzt sind. §1: Die Empfehlungen beziehen sich im Wesentlichen auf Wasserwirtschaft, Wasserbau, Abwasser und Abfall; Teil 2 umfasst die Phasen von der Bedarfsplanung (LPH 0) bis zur Objektbetreuung (LPH 9).
[EN] Blocks approval until the primary sector and at least one commissioned HOAI phase are set. §1: the recommendations relate essentially to water management, hydraulic engineering, wastewater and waste; Part 2 covers needs planning (LPH 0) to object support (LPH 9).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-01' AND x.code = 'REQ-01';
UPDATE fields x SET description = 'Bestätigung des Ingenieurs, dass die Projektziele stabil sind, bevor die Planung darauf aufbaut. §5.3.3 verlangt eindeutig definierte Ziele mit dauerhaftem Bestand.
[EN] Engineer''s confirmation that the project goals are stable before downstream design builds on them. §5.3.3 requires clearly defined goals that remain in force.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.symbol = 'goals_stability_signoff';
UPDATE fields x SET description = 'Name des Betreibers. §2.1 zählt den Betreiber zum Auftraggeber ("Auftraggeber (Bauherr und Betreiber)"); relevant u.a. für Inbetriebnahme und Übergabe in §5.7.
[EN] Name of the operator. §2.1 counts the operator as part of the client ("Auftraggeber (Bauherr und Betreiber)"); relevant among other things for commissioning and handover in §5.7.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.symbol = 'operator_betreiber';
UPDATE fields x SET description = 'Register der Projektziele nach den vier Kategorien aus DIN 18205 Tab. A.2: funktional/technisch, soziokulturell/gestalterisch, ökonomisch/zeitlich, ökologisch. §5.3.3 verlangt eindeutige, dauerhaft bestandsfähige Ziele.
[EN] Register of project goals under the four DIN 18205 Tab. A.2 categories: functional/technical, sociocultural/design, economic/schedule, ecological. §5.3.3 requires clearly defined goals that remain valid.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.symbol = 'project_goals';
UPDATE fields x SET description = 'Bestätigung, dass Kommunikationsweise, Verbindlichkeit von Zusagen, Entscheidungsform und die Beratungsfunktion des Auftragnehmerteams beim Projektaufsatz geklärt wurden - die Bausteine der "Projektkultur" nach §3.
[EN] Confirmation that communication style, how firmly commitments bind, the form of decisions, and the contractor team''s advisory role were clarified at project setup - the building blocks of "project culture" under §3.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.symbol = 'projektkultur_documented';
UPDATE fields x SET description = 'Register der Beteiligten und Betroffenen mit Rolle, Verantwortung und Kommunikationsweg. §3/Bild 1 benennt Auftraggeber, Auftragnehmer, Behörden, Öffentlichkeit und ausführende Firmen als Kommunikationspartner.
[EN] Register of stakeholders and affected parties with role, responsibility and communication channel. §3/Bild 1 names the client, contractor, authorities, public and executing firms as communication partners.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.symbol = 'stakeholders_list';
UPDATE compliance_requirements x SET description = 'Warnt (unverbindlich), solange das Beteiligten-Register leer ist. §3/Bild 1: "Eine Analyse der Beteiligten und Betroffenen sowie der Umgang mit ihnen wird als wichtig angesehen" - erfasst werden Auftraggeber, Behörden, Öffentlichkeit, ausführende Firmen u.a.
[EN] Warns (non-blocking) while the stakeholder register is empty. §3/Bild 1: "an analysis of the stakeholders and affected parties and how they are handled is considered important" - covering client, authorities, public, executing firms etc.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.code = 'REQ-02';
UPDATE compliance_requirements x SET description = 'Warnt (unverbindlich), solange das Projektziel-Register leer ist oder goals_stability_signoff nicht bestätigt ist. §5.3.3: Ziele müssen eindeutig definiert sein und dauerhaft Bestand haben; vor Änderung einer Zielvorgabe ist eine umfassende Prüfung der Auswirkungen zwingend.
[EN] Warns (non-blocking) while the project-goal register is empty or goals_stability_signoff is not confirmed. §5.3.3: goals must be clearly defined and remain valid; a full impact check before changing a goal is mandatory.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-02' AND x.code = 'REQ-26';
UPDATE fields x SET description = 'Freitext zum projektspezifischen Kommunikationskonzept (intern/öffentlich). §5.3.1 verlangt, dass Kommunikation regelmäßig, vorbereitet, effektiv und dokumentiert ist.
[EN] Free text describing the project-specific communication concept (internal/public). §5.3.1 requires communication to be regular, prepared, effective and documented.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'communication_concept';
UPDATE fields x SET description = 'Vertragsart (Planungs-, Bau-, Rahmen- oder Losvertrag). Projektangabe; sie wird auf 820-2-09 und 820-2-17 angezeigt und steuert keine Prüfung.
[EN] Contract type (planning, construction, framework or lot-based). A project record shown on 820-2-09 and 820-2-17; it drives no check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'contract_type';
UPDATE fields x SET description = 'Ob die Honorierung auf der HOAI basiert. §2.2 führt "HOAI" nur als Abkürzung; die gedruckte Warnung steht in §4.1: selbst alle HOAI-Grundleistungen ergeben noch keine umfassende Projektmanagementleistung.
[EN] Whether fees follow the HOAI scale. §2.2 lists "HOAI" only as an abbreviation; the printed caveat is in §4.1: even all HOAI Grundleistungen together do not amount to comprehensive project management.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'hoai_compliance';
UPDATE fields x SET description = 'Ob VOB/A und VOB/B für die Baulose gelten. §2.2 führt VOB/A und VOB/B nur als Abkürzungen; keine eigene Anwendungsregel in diesem Merkblatt.
[EN] Whether VOB/A and VOB/B apply to the construction lots. §2.2 lists VOB/A and VOB/B only as abbreviations; this guideline sets no applicability rule of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'vob_applicable';
UPDATE fields x SET description = 'Register der Projektkorrespondenz (E-Mail, Brief, Telefonat, Besprechung): eine Zeile je Vorgang. Pflicht je Zeile: Datum, Richtung, Betreff; mit "Nachverfolgung nötig" und "erledigt" wird offene Nachverfolgung gezählt. §5.3.1: "Die Kommunikation muss regelmäßig, vorbereitet, effektiv und dokumentiert sein." Nicht verpflichtend.
[EN] Register of project correspondence (email, letter, call, meeting): one row per item. Required per row: date, direction, subject; "follow-up needed" and "done" feed the open follow-up count. §5.3.1: "Communication must be regular, prepared, effective and documented." Not required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'korrespondenz';
UPDATE fields x SET description = 'Zählt die vollständigen Zeilen (Datum, Richtung, Betreff) des Korrespondenz-Registers. Rein informativ, kein Gate.
[EN] Counts the complete rows (date, direction, subject) of the correspondence register. Informational only, no gate reads it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'korrespondenz_count';
UPDATE fields x SET description = 'Zählt Korrespondenz-Zeilen mit offener Nachverfolgung. §5.3.1 benennt es als Problem, wenn Ergebnisse und Entscheidungen "anschließend nicht nachverfolgt" werden. Kein Gate.
[EN] Counts correspondence rows with an open follow-up. §5.3.1 names it as a problem when results and decisions are "not followed up" afterwards. No gate reads it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.symbol = 'korrespondenz_nachverfolgung_offen';
UPDATE equations x SET description = 'Zählt die vollständig ausgefüllten Zeilen (Datum, Richtung, Betreff) im Korrespondenz-Register.
[EN] Counts the fully filled rows (date, direction, subject) in the correspondence register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.equation_number = '820-2-03-D1';
UPDATE equations x SET description = 'Zählt Korrespondenz-Zeilen, die als nachverfolgungsbedürftig markiert, aber noch nicht erledigt sind - der im Merkblatt beschriebene Fehlerfall "nicht nachverfolgt".
[EN] Counts correspondence rows flagged as needing follow-up but not yet done - the failure mode the guideline describes as "not followed up".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-03' AND x.equation_number = '820-2-03-D2';
UPDATE fields x SET description = 'Register der für das Projekt geltenden DIN-Normen mit Titel und Geltungsbereich. §6.1 verlangt, dass die vom Auftraggeber verwendeten Richtlinien und Regelwerke aktuell, widerspruchsfrei, in Übereinstimmung mit Normen und handhabbar sind.
[EN] Register of the DIN standards applicable to the project, with title and scope. §6.1 requires the client''s own guidelines and Regelwerke to be current, free of contradiction, consistent with standards and workable.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-04' AND x.symbol = 'applicable_din_standards';
UPDATE fields x SET description = 'Register der für das Projekt geltenden DWA-/ATV-Regelwerke mit Titel und Geltungsbereich. Die eigenen Richtlinien des Auftraggebers müssen nach §6.1 mit diesen Normen und Regeln übereinstimmen.
[EN] Register of the DWA/ATV rules applicable to the project, with title and scope. Per §6.1 the client''s own guidelines must be consistent with these standards and rules.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-04' AND x.symbol = 'applicable_dwa_standards';
UPDATE fields x SET description = 'Register der eigenen Richtlinien des Auftraggebers - nach §6.2 technische (z.B. Kennzeichnungssystem AKZ) oder organisatorische (z.B. Betriebssatzung). Nicht verpflichtend.
[EN] Register of the client''s own guidelines - per §6.2 technical (e.g. AKZ labelling system) or organisational (e.g. Betriebssatzung). Not required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-04' AND x.symbol = 'client_guidelines';
UPDATE fields x SET description = 'Bestätigt, dass die dem Projekt zugrunde liegenden Regelwerke auf Aktualität geprüft sind. §6.3.1: "Die Regelwerke müssen ... stets auf dem neuesten Stand sein." §6.3.2 schlägt vor, sie zu Projektbeginn auf Aktualität zu prüfen und aufzulisten.
[EN] Confirms the Regelwerke underlying the project have been checked for currency. §6.3.1: the Regelwerke "must ... always be up to date". §6.3.2 suggests checking and listing them for currency at project start.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-04' AND x.symbol = 'regulations_current_check';
UPDATE compliance_requirements x SET description = 'Blockiert, bis regulations_current_check bestätigt ist. §6.3.1: Die Regelwerke müssen frei von Widersprüchen und stets auf dem neuesten Stand sein; §6.3.2: Es besteht die Verpflichtung, die (auf das notwendige Maß reduzierten) Regelwerke vollständig anzuwenden.
[EN] Blocks until regulations_current_check is confirmed. §6.3.1: the Regelwerke must be free of contradiction and always up to date; §6.3.2: there is an obligation to apply the (reduced-to-necessary) Regelwerke in full.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-04' AND x.code = 'REQ-53';
UPDATE fields x SET description = 'Bestätigt, dass nicht delegierbare Bauherrenaufgaben (Umfang, Automatisierungsgrad, Redundanz, Betriebs-/Qualitätsanforderungen) dokumentiert und wahrgenommen werden. §4.3.2: "Jeder Projektbeteiligte muss genau wissen, welches seine Aufgaben sind", klar und eindeutig beschrieben, mit kompetenten, verfügbaren Ansprechpartnern.
[EN] Confirms the Bauherr''s non-delegable tasks (scope, automation level, redundancy, operating/quality requirements) are documented and carried out. §4.3.2: "every project participant must know exactly what his tasks are", clearly described, with available, competent contacts named.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'bauherr_tasks_defined';
UPDATE fields x SET description = 'Bestätigt, dass Entscheidungsbefugnisse, Wertgrenzen und Eskalationswege festgelegt sind. §4.3.3: "Entscheidungskompetenzen sind zu analysieren und für die konkreten Projekte zu beschreiben."
[EN] Confirms decision authority, value thresholds and escalation paths are mapped. §4.3.3: "decision competencies are to be analysed and described for the specific project."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'decision_competencies_mapped';
UPDATE fields x SET description = 'Bestätigt, dass Erwartungen zwischen allen Beteiligten aktiv abgeglichen werden. §4.3.1: ergänzend zum Erwartungsmanagement "ist das Beziehungsmanagement aller Beteiligten erforderlich".
[EN] Confirms that expectations between all parties are actively reconciled. §4.3.1: alongside expectations management, "relationship management among all parties is required".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'expectations_management_active';
UPDATE fields x SET description = 'Bestätigt die Phase "Durchführen" des Management-Regelkreises: die Leistungserbringung aller Projektbeteiligten (Auftraggeber, Auftragnehmer, Gutachter, ausführende Firmen). Beschreibung aus §4.2, kein eigener Modalverb-Satz.
[EN] Confirms the "Execute" step of the management cycle: delivery of work by all parties (client, contractor, experts, executing firms). Descriptive definition from §4.2, no modal-verb requirement of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'mgmt_cycle_durchfuehren';
UPDATE fields x SET description = 'Takt, in dem der Management-Regelkreis (Planen-Durchführen-Kontrollieren-Steuern) durchlaufen wird. §4.2 nennt zwei- bis vierwöchige Abstände als üblichen Rhythmus.
[EN] Cadence at which the management cycle (Plan-Do-Check-Steer) is run. §4.2 names a two- to four-week interval as the usual rhythm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'mgmt_cycle_frequency';
UPDATE fields x SET description = 'Bestätigt die Phase "Planen": ein realistischer, belastbarer Kosten- und Terminplan (Kostenziel nach DIN 276 inkl. Risiken/Reserven; Terminziel Fertigstellungstermin), mit Fortschreibung bei Bedarf. Beschreibung aus §4.2.
[EN] Confirms the "Plan" step: a realistic, robust cost and schedule plan (cost target per DIN 276 incl. risks/reserves; schedule target the completion date), updated as needed. Descriptive definition from §4.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'mgmt_cycle_planen';
UPDATE fields x SET description = 'Bestätigt, dass das Projekthandbuch dem Gliederungsvorschlag aus Anhang B folgt. §4.3.5: "Das Projekthandbuch ist aktuell zu halten, regelmäßig ... auf Lücken zu prüfen und geeignet zu ergänzen"; wird es Vertragsbestandteil, ist es verbindlich.
[EN] Confirms the project handbook follows the Annex B structure. §4.3.5: "the project handbook is to be kept current, checked regularly ... for gaps and suitably completed"; once part of the contract it is binding.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'project_handbook_complete';
UPDATE fields x SET description = 'Bestätigt, dass die Projektleitung als Linienfunktion im Organigramm verankert ist - abgegrenzt von der Projektsteuerung, die §4.1 als "Stabsstelle" dazu beschreibt.
[EN] Confirms project leadership (Projektleitung) sits in the organigram as a line function - distinct from project steering (Projektsteuerung), which §4.1 describes as a "staff function" alongside it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'project_leadership_function';
UPDATE fields x SET description = 'Mehrfachauswahl der Handlungsbereiche der Projektsteuerung. §4.1 nennt Projektorganisation, Terminmanagement, Kostenmanagement, Qualitätsmanagement und Vertragsmanagement; Risikomanagement ergänzt aus §4.8.
[EN] Multi-select of the Projektsteuerung''s action areas. §4.1 names project organisation, schedule, cost, quality and contract management; risk management is added from §4.8.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'projektsteuerung_scope';
UPDATE fields x SET description = 'Mehrfachauswahl über die acht gedruckten Kapitel des Gliederungsvorschlags in Anhang B (1 Aufbau und Organisation ... bis 8 Kostenmanagement) - ein Anhaltswert, keine abschließende Liste.
[EN] Multi-select over the eight printed chapters of the Annex B structure proposal (1 Setup and organisation ... to 8 Cost management) - a guideline template, not an exhaustive list.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'projekthandbuch_kapitel';
UPDATE fields x SET description = 'Register der Projektschritte: eine Zeile je Arbeitsschritt mit Datum, Schritt, Verantwortlich, Ergebnis, Nachweis, Status. Pflicht je Zeile: Schritt und Status (geplant, in Arbeit, erledigt). §4.1 nennt "Aufgabenverfolgung und Plandokumentation" als notwendig. Nicht verpflichtend.
[EN] Register of project steps: one row per work step with date, step, responsible, result, evidence, status. Required per row: step and status (planned, in progress, done). §4.1 calls "task tracking and plan documentation" necessary. Not required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'projektschritte';
UPDATE fields x SET description = 'Zählt die vollständig ausgefüllten Zeilen (Schritt und Status) des Projektschritte-Registers. Rein informativ, kein Gate.
[EN] Counts the complete rows (step and status filled) of the project-steps register. Informational only, no gate reads it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'projektschritte_count';
UPDATE fields x SET description = 'Zählt Projektschritte mit Status ungleich "erledigt" (geplant oder in Arbeit). Kein Gate.
[EN] Counts project steps whose status is not "done" (planned or in progress). No gate reads it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'projektschritte_offen';
UPDATE fields x SET description = 'Bestätigung, dass der Betrieb bereits in Konzeption und Bedarfsplanung aktiv eingebunden war. §4.3.4 (Vorschlag zur Verbesserung): "Bereits in der Phase der Konzeption und Bedarfsplanung wird der Betrieb aktiv eingebunden." Nicht verpflichtend.
[EN] Confirms the operator was already actively involved during concept work and needs planning. §4.3.4 (improvement suggestion): "the operator is actively involved already in the concept and needs-planning phase." Not required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.symbol = 'betrieb_frueh_eingebunden';
UPDATE equations x SET description = 'Zählt die vollständig ausgefüllten Zeilen (Schritt, Status) des Projektschritte-Registers.
[EN] Counts the complete rows (step, status filled) of the project-steps register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.equation_number = '820-2-05-D1';
UPDATE equations x SET description = 'Zählt Zeilen des Projektschritte-Registers mit Status ungleich "erledigt".
[EN] Counts project-steps rows whose status is not "done".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.equation_number = '820-2-05-D2';
UPDATE compliance_requirements x SET description = 'Blockiert, bis bauherr_tasks_defined bestätigt ist. §4.3.2: "Jeder Projektbeteiligte muss genau wissen, welches seine Aufgaben sind", mit verfügbaren, kompetenten Ansprechpartnern.
[EN] Blocks until bauherr_tasks_defined is confirmed. §4.3.2: "every project participant must know exactly what his tasks are", with available, competent contacts named.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.code = 'REQ-04';
UPDATE compliance_requirements x SET description = 'Blockiert, bis decision_competencies_mapped bestätigt ist. §4.3.3: Entscheidungskompetenzen sind zu analysieren und für das konkrete Projekt zu beschreiben.
[EN] Blocks until decision_competencies_mapped is confirmed. §4.3.3: decision competencies are to be analysed and described for the specific project.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.code = 'REQ-05';
UPDATE compliance_requirements x SET description = 'Warnt (unverbindlich), solange betrieb_frueh_eingebunden nicht bestätigt ist. §4.3.4 nennt als Ziel: der Betrieb wird bereits in Konzeption und Bedarfsplanung aktiv eingebunden.
[EN] Warns (non-blocking) while betrieb_frueh_eingebunden is not confirmed. §4.3.4 names the target state: the operator is already actively involved in the concept and needs-planning phase.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.code = 'REQ-06';
UPDATE compliance_requirements x SET description = 'Blockiert, bis project_handbook_complete bestätigt ist. §4.3.5: Das Projekthandbuch ist aktuell zu halten, regelmäßig auf Lücken zu prüfen und geeignet zu ergänzen; Inhalt und Umfang richten sich nach der Komplexität des Projekts. Anhang B enthält einen Gliederungsvorschlag. Wird es Vertragsbestandteil, ist es verbindlich.
[EN] Blocks until project_handbook_complete is confirmed. §4.3.5: the handbook is to be kept current, regularly checked for gaps and suitably completed; content and scope follow the project''s complexity. Annex B contains a structure proposal. Once part of the contract it is binding.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-05' AND x.code = 'REQ-07';
UPDATE fields x SET description = 'Bestätigt, dass jede akzeptierte Änderung mit dokumentierter Auswirkung auf Termine/Kosten/Qualität vorliegt. §2.1 (Änderungsmanagement): "die Auswirkungen auf die Termine, die Kosten und die Qualitäten sind zu eruieren und als Grundlage für eine Entscheidung dem Auftraggeber vorzulegen."
[EN] Confirms every accepted change carries a documented impact on schedule/cost/quality. §2.1 (Änderungsmanagement definition): "the effects on schedule, costs and quality are to be ascertained and submitted to the client as the basis for a decision."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.symbol = 'change_impact_documented';
UPDATE fields x SET description = 'Bestätigt, dass eine Liste offener Punkte (LOP) und ein Änderungsregister geführt werden. §4.3.7: Im Projekthandbuch sind der Prozess für das Änderungsmanagement sowie die anzuwendenden Formulare bereitgestellt.
[EN] Confirms an open-items list (LOP) and a change register are kept. §4.3.7: the project handbook provides the change-management process and the forms to use.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.symbol = 'change_log_present';
UPDATE fields x SET description = 'Bestätigt die Phase "Kontrollieren": Soll-Ist-Vergleich von Kosten und Terminen; die Abweichungsanalyse zeigt den Einfluss auf Zieländerungen. Beschreibung aus §4.2.
[EN] Confirms the "Control" step: a target-vs-actual comparison of cost and schedule; the deviation analysis shows the impact on goal changes. Descriptive definition from §4.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.symbol = 'mgmt_cycle_kontrollieren';
UPDATE fields x SET description = 'Bestätigt die Phase "Steuern": anhand der Abweichungsanalyse werden Maßnahmen erarbeitet, mit denen die vereinbarten Ziele wieder eingehalten werden können. Beschreibung aus §4.2.
[EN] Confirms the "Steer" step: based on the deviation analysis, measures are worked out to bring the project back to the agreed targets. Descriptive definition from §4.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.symbol = 'mgmt_cycle_steuern';
UPDATE fields x SET description = 'Takt der Statusberichte. §4.3.6: "In der Regel werden mindestens vierteljährliche Statusberichte konsequent geführt"; die Frequenz orientiert sich am Projekt- oder Baufortschritt.
[EN] Cadence of status reports. §4.3.6: "as a rule, at least quarterly status reports are kept consistently"; the frequency follows the project or construction progress.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.symbol = 'status_report_frequency';
UPDATE fields x SET description = 'Mehrfachauswahl über die in Anhang A vorgeschlagenen 19 Abschnitte plus 2 Anlagen eines Statusberichts - ein Gliederungsvorschlag (Anhaltswert), keine Pflichtliste.
[EN] Multi-select over the 19 sections plus 2 annexes Annex A proposes for a status report - a structure template, not a mandatory list.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.symbol = 'statusbericht_abschnitte';
UPDATE fields x SET description = 'Liste offener Punkte (LOP): eine Zeile je offenem Punkt mit Status (offen/erledigt). §5.3.1: Besprechungen werden mindestens mit Tagesordnung, LOP und Zeitplanung vorbereitet. Nicht verpflichtend.
[EN] List of open items (LOP): one row per open item with status (open/done). §5.3.1: meetings are prepared at least with agenda, LOP and time plan. Not required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.symbol = 'offene_punkte';
UPDATE fields x SET description = 'Zählt die Zeilen des LOP-Registers. Rein informativ.
[EN] Counts the rows of the LOP register. Informational only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.symbol = 'lop_count';
UPDATE fields x SET description = 'Zählt LOP-Zeilen mit Status "offen". Kein Gate.
[EN] Counts LOP rows with status "open". No gate reads it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.symbol = 'lop_open';
UPDATE fields x SET description = 'Register der erstellten Statusberichte: eine Zeile je Bericht mit Nr., Datum, Berichtszeitraum, Ampeln, erstellt/freigegeben von, Verteiler. Pflicht je Zeile: Nr. und Datum. §4.3.6: "Der Verteiler der Berichte muss sorgfältig vom Auftraggeber festgelegt werden und enthält immer auch das Planungsteam." Nicht verpflichtend.
[EN] Register of issued status reports: one row per report with no., date, reporting period, traffic lights, prepared/released by, distribution. Required per row: no. and date. §4.3.6: "the distribution must be carefully fixed by the client and always includes the planning team." Not required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.symbol = 'statusberichte';
UPDATE fields x SET description = 'Zählt die vollständigen Zeilen (Nr., Datum) des Statusbericht-Registers. Kein Gate - der im Merkblatt genannte vierteljährliche Turnus steht unter "in der Regel".
[EN] Counts the complete rows (no., date) of the status-report register. No gate reads it - the quarterly cadence the guideline names is qualified "as a rule".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.symbol = 'statusberichte_count';
UPDATE equations x SET description = 'Zählt die Zeilen der Liste offener Punkte (LOP).
[EN] Counts the rows of the open-items list (LOP).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.equation_number = '820-2-06-D1';
UPDATE equations x SET description = 'Zählt LOP-Zeilen mit Status "offen".
[EN] Counts LOP rows with status "open".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.equation_number = '820-2-06-D2';
UPDATE equations x SET description = 'Zählt die vollständigen Zeilen (Nr., Datum ausgefüllt) des Statusbericht-Registers.
[EN] Counts the complete rows (no., date filled) of the status-report register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.equation_number = '820-2-06-D3';
UPDATE compliance_requirements x SET description = 'Warnt, solange status_report_frequency nicht gesetzt ist. §4.3.6 beschreibt als Zielbild: Statusberichte nach dem Gliederungsvorschlag in Anhang A, mit fester Frequenz (i.d.R. mind. vierteljährlich) und einem sorgfältig festgelegten Verteiler.
[EN] Warns while status_report_frequency is unset. §4.3.6 describes the target state: status reports following the Annex A structure, at a fixed cadence (as a rule at least quarterly), with a carefully fixed distribution list.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.code = 'REQ-08';
UPDATE compliance_requirements x SET description = 'Blockiert, bis change_log_present UND change_impact_documented bestätigt sind. §2.1 (Änderungsmanagement): Auswirkungen auf Termine, Kosten, Qualitäten sind vor jeder endgültigen Festlegung zu eruieren und dem Auftraggeber als Entscheidungsgrundlage vorzulegen.
[EN] Blocks until BOTH change_log_present and change_impact_documented are confirmed. §2.1 (Änderungsmanagement definition): effects on schedule, cost and quality are to be ascertained before any final decision and submitted to the client as the basis for it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-06' AND x.code = 'REQ-09';
UPDATE fields x SET description = 'Bestätigt, dass der Auftragnehmer Know-how und Ressourcen für aktives Terminmanagement hat. §4.4.3: er "beherrscht" Netzplantechnik und geeignete Softwareprogramme und beteiligt sich aktiv am Terminmanagement.
[EN] Confirms the contractor has the know-how and resources for active schedule management. §4.4.3: he "masters" network-planning technique and suitable software and takes an active part in schedule management.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-07' AND x.symbol = 'contractor_schedule_resources';
UPDATE fields x SET description = 'Bestätigt, dass ein Termindetailplan vorliegt. §4.4.1 definiert Detailterminpläne bzw. Bauzeitenpläne als finale Detaillierungsstufe von Auftragnehmer und ausführenden Firmen zur Planung und Koordinierung der eigenen Leistungen.
[EN] Confirms a detailed schedule (Termindetailplan) exists. §4.4.1 defines detail/Bauzeiten schedules as the final level of detail used by the contractor and executing firms to plan and coordinate their own work.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-07' AND x.symbol = 'detailed_schedule_present';
UPDATE fields x SET description = 'Bestätigt, dass ein Rahmenterminplan vorliegt. §4.4.1: Rahmenterminpläne enthalten hauptsächlich die wesentlichen Meilensteine und sind übersichtlich; nach §5.5.4 (Zielbild) ist den Vergabeunterlagen ein realistischer Terminplan mit Pufferzeiten beigefügt.
[EN] Confirms a master schedule exists. §4.4.1: master schedules mainly carry the key milestones and are concise; per §5.5.4 (target state) a realistic schedule with buffers is attached to the tender documents.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-07' AND x.symbol = 'master_schedule_present';
UPDATE compliance_requirements x SET description = 'Blockiert, bis master_schedule_present UND detailed_schedule_present bestätigt sind. §4.4.2: der Auftraggeber hat die "Terminhoheit"; das eingesetzte Personal hat die nötige Kapazität und das Know-how (Netzplantechnik), die Terminziele sind realistisch geplant.
[EN] Blocks until BOTH master_schedule_present and detailed_schedule_present are confirmed. §4.4.2: the client holds "schedule sovereignty"; staff have the necessary capacity and know-how (network-planning technique), and the schedule targets are realistically planned.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-07' AND x.code = 'REQ-10';
UPDATE compliance_requirements x SET description = 'Blockiert, bis contractor_schedule_resources bestätigt ist. §4.4.3: der Auftragnehmer beherrscht Netzplantechnik und geeignete Softwareprogramme und beteiligt sich aktiv am Terminmanagement.
[EN] Blocks until contractor_schedule_resources is confirmed. §4.4.3: the contractor masters network-planning technique and suitable software and takes an active part in schedule management.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-07' AND x.code = 'REQ-11';
UPDATE fields x SET description = 'Bestätigt aktives Kostencontrolling mit Soll-Ist-Vergleich. §4.5.4: "Die Kostensituation eines Projekts sollte zu jedem Zeitpunkt der Planungs- und Bauphase bekannt sein", einschließlich Nachträgen und Kostenprognose.
[EN] Confirms active cost controlling with a target-vs-actual comparison. §4.5.4: "the cost situation of a project should be known at every point of the planning and construction phase", including change orders and the cost forecast.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND x.symbol = 'cost_control_documented';
UPDATE fields x SET description = 'Bestätigt Kostenplanung nach DIN 276-Kostengruppen. §4.5.1: "Eine einheitliche und durchgängige Kostenstruktur ist im Projekt vereinbart (bspw. DIN 276)."
[EN] Confirms cost planning structured by DIN 276 cost groups. §4.5.1: "a uniform, consistent cost structure is agreed for the project (e.g. DIN 276)."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND x.symbol = 'cost_planning_din276';
UPDATE fields x SET description = 'Bestätigt, dass der Lebenszyklusansatz angewendet wurde. §2.1 definiert Lebenszykluskosten (LZK) als alle Kosten von Entwicklung bis Rückbau, wobei "auch die Erlöse zu betrachten" sind.
[EN] Confirms the lifecycle-cost approach was applied. §2.1 defines lifecycle costs (LZK) as all costs from development to decommissioning, where "the proceeds are also to be considered".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND x.symbol = 'life_cycle_cost_considered';
UPDATE fields x SET description = 'Bestätigt, dass der Auftragnehmer den Auftraggeber über Kosteninhalte, erzielbare Genauigkeit und Risiken informiert hat. §4.5.3: "Der Auftragnehmer weist den Auftraggeber auf die Inhalte der zu ermittelnden Kosten ... sowie die erzielbare Genauigkeit und mögliche Risiken hin."
[EN] Confirms the contractor has briefed the client on cost content, achievable accuracy and risks. §4.5.3: "the contractor advises the client on the content of the costs to be determined ... as well as the achievable accuracy and possible risks."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND x.symbol = 'kostenhinweise_auftragnehmer';
UPDATE fields x SET description = 'Bestätigt, dass ein Prozess für Änderungen der Projektinhalte existiert. §4.5.5: "Es ist ein Prozessablauf festgelegt, wie mit Änderungen der Projektinhalte umgegangen werden muss"; danach sind die Kostenziele neu zu erarbeiten, festzulegen und zu beschließen.
[EN] Confirms a process exists for changes to project content. §4.5.5: "a process is laid down for how changes to project content must be handled"; following it, the cost targets are to be re-worked, fixed and resolved.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND x.symbol = 'kostenziele_aenderungsprozess';
UPDATE compliance_requirements x SET description = 'Blockiert, bis cost_planning_din276 bestätigt ist. §4.5.2: der Auftraggeber hat den Kostenüberblick geschaffen; "Die Kostenziele müssen als Grundlage für die Finanzierung ... realistisch geplant sein."
[EN] Blocks until cost_planning_din276 is confirmed. §4.5.2: the client has established the cost overview; "the cost targets must be realistically planned as the basis for financing ..."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND x.code = 'REQ-12';
UPDATE compliance_requirements x SET description = 'Warnt, solange kostenhinweise_auftragnehmer nicht bestätigt ist. §4.5.3: der Auftragnehmer weist den Auftraggeber auf Kosteninhalte (Abgrenzung zu DIN 276), erzielbare Genauigkeit und Risiken hin.
[EN] Warns while kostenhinweise_auftragnehmer is not confirmed. §4.5.3: the contractor advises the client on cost content (delimited against DIN 276), achievable accuracy and risks.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND x.code = 'REQ-13';
UPDATE compliance_requirements x SET description = 'Blockiert, bis cost_control_documented bestätigt ist. §4.5.4: "Die Kostensituation eines Projekts sollte zu jedem Zeitpunkt der Planungs- und Bauphase bekannt sein", einschließlich Nachträgen und Kostenprognose.
[EN] Blocks until cost_control_documented is confirmed. §4.5.4: "the cost situation of a project should be known at every point of the planning and construction phase", including change orders and the cost forecast.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND x.code = 'REQ-14';
UPDATE compliance_requirements x SET description = 'Warnt, solange kostenziele_aenderungsprozess nicht bestätigt ist. §4.5.5: ein Prozess für Änderungen der Projektinhalte ist festgelegt; danach werden die Kostenziele neu erarbeitet, festgelegt und beschlossen.
[EN] Warns while kostenziele_aenderungsprozess is not confirmed. §4.5.5: a process for changes to project content is laid down; following it, cost targets are re-worked, fixed and resolved.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-08' AND x.code = 'REQ-15';
UPDATE fields x SET description = 'Bestätigt, dass Freigabe- und Abnahmeverfahren für Planungsleistungen geregelt sind. §4.6.2 (Ziel): nach jeder abgeschlossenen Leistungsphase erfolgt eine Freigabe; im Vertrag wird festgelegt, dass Teilabnahmen möglich sind.
[EN] Confirms approval and acceptance procedures for planning deliverables are regulated. §4.6.2 (target state): a release follows each completed phase; the contract lays down that partial acceptances are possible.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND x.symbol = 'approval_procedure_defined';
UPDATE fields x SET description = 'Bestätigt, dass umfangsrelevante Änderungen im Vertrag fortgeschrieben werden. §4.6.1: "Es sollten gute Verträge geschlossen werden ... Ein Vertrag wird geschlossen, bei dem Änderungen nachvollziehbar fortgeschrieben werden."
[EN] Confirms scope-relevant changes are tracked in a contract amendment. §4.6.1: "good contracts should be concluded ... a contract is concluded in which changes are traceably updated."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND x.symbol = 'contract_amendments_tracked';
UPDATE fields x SET description = 'Bestätigung, dass HOAI-Grundleistungen allein keine umfassende Projektmanagementleistung ersetzen. §4.1: "Dem Auftraggeber muss bewusst sein, dass selbst bei Verwendung aller Grundleistungen der HOAI keine umfassenden Projektmanagementleistungen beauftragt sind."
[EN] Acknowledges HOAI Grundleistungen alone do not substitute for comprehensive project management. §4.1: "the client must be aware that even when using all HOAI Grundleistungen, no comprehensive project-management services are commissioned."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND x.symbol = 'hoai_grundleistungen_limits';
UPDATE fields x SET description = 'Bestätigt, dass ein Qualitätssicherungs-/-überwachungsplan für die Bauüberwachung (LPH 8) vorliegt. §4.7.2 (Ziel): "Ein fundierter Qualitätssicherungsplan ... wird gemeinsam erstellt und aktiv umgesetzt." Nur sichtbar, solange LPH 8 stattfindet.
[EN] Confirms a quality-assurance/-monitoring plan for site supervision (LPH 8) exists. §4.7.2 (target state): "a sound quality-assurance plan ... is jointly drawn up and actively implemented." Only shown while LPH 8 takes place.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND x.symbol = 'qs_plan_lph8_present';
UPDATE fields x SET description = 'Bestätigt aktive Qualitätsüberwachung der Planungsleistung. §4.7.1 (Ziel): eine phasenbezogene Prüfung wird in einem Qualitätssicherungsplan festgelegt, der Eigen- und Fremdüberwachung regelt.
[EN] Confirms active quality monitoring of the planning work. §4.7.1 (target state): a phase-by-phase check is laid down in a quality-assurance plan covering both self- and third-party monitoring.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND x.symbol = 'quality_monitoring_active';
UPDATE compliance_requirements x SET description = 'Blockiert, bis contract_amendments_tracked bestätigt ist. §4.6.1: Verträge werden bei Leistungsänderungen nachvollziehbar fortgeschrieben.
[EN] Blocks until contract_amendments_tracked is confirmed. §4.6.1: contracts are traceably updated whenever the scope of services changes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND x.code = 'REQ-16';
UPDATE compliance_requirements x SET description = 'Blockiert, bis approval_procedure_defined bestätigt ist. §4.6.2: nach jeder abgeschlossenen Leistungsphase erfolgt eine Freigabe; Teilabnahmen werden vertraglich geregelt.
[EN] Blocks until approval_procedure_defined is confirmed. §4.6.2: a release follows each completed phase; partial acceptances are regulated by contract.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND x.code = 'REQ-17';
UPDATE compliance_requirements x SET description = 'Blockiert, bis quality_monitoring_active bestätigt ist. §4.7.1: eine phasenbezogene Qualitätsprüfung wird in einem Qualitätssicherungsplan (Eigen- + Fremdüberwachung) festgelegt.
[EN] Blocks until quality_monitoring_active is confirmed. §4.7.1: a phase-by-phase quality check is laid down in a quality-assurance plan (self- and third-party monitoring).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND x.code = 'REQ-18';
UPDATE compliance_requirements x SET description = 'Blockiert, bis qs_plan_lph8_present bestätigt ist - nur solange LPH 8 stattfindet (820-2-01: verantwortung_lph8 != entfällt). §4.7.2: ein Qualitätssicherungsplan für die Bauüberwachung wird gemeinsam erstellt und aktiv umgesetzt.
[EN] Blocks until qs_plan_lph8_present is confirmed - only while LPH 8 takes place (820-2-01: verantwortung_lph8 != does-not-occur). §4.7.2: a quality-assurance plan for site supervision is jointly drawn up and actively implemented.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-09' AND x.code = 'REQ-19';
UPDATE fields x SET description = 'Bestätigt faire Risikoverteilung zwischen Auftraggeber und Auftragnehmer. §3: "Die Risikoverteilung darf keinen Einfluss auf das Planungsergebnis haben."
[EN] Confirms the risk split between client and contractor is fair. §3: "the risk distribution must not influence the planning outcome."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-10' AND x.symbol = 'risk_distribution_fair';
UPDATE fields x SET description = 'Bestätigt, dass ein systematisches Risikoregister mit Eintrittswahrscheinlichkeit/Schaden existiert. §4.8.2: "Eine sorgfältig erstellte Risikoanalyse ist die Grundlage für ein wirksames Risikomanagement."
[EN] Confirms a systematic risk register with probability/impact ratings exists. §4.8.2: "a carefully prepared risk analysis is the basis for effective risk management."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-10' AND x.symbol = 'risk_register_present';
UPDATE fields x SET description = 'Risikoregister nach DWA-M 820-1 Anhang A (Tab. A.1), auf das §4.8.2 verweist; die Einträge werden aus der Risikoanalyse von DWA-M 820-1 übernommen. Eine Zeile je Risiko: Risikogruppe, Risiko (Pflicht), Bewertung Eintrittswahrscheinlichkeit × Schaden durch Bauherr, Planer, Betrieb. Nicht verpflichtend.
[EN] Risk register per DWA-M 820-1 Annex A (Tab. A.1), referenced by §4.8.2; entries are carried over from the DWA-M 820-1 risk analysis. One row per risk: risk group, risk (required), probability x damage rating by client, planner, operator. Not required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-10' AND x.symbol = 'risk_register';
UPDATE fields x SET description = 'Zählt Zeilen des Risikoregisters mit benanntem Risiko. Rein informativ - REQ-20 liest weiterhin risk_register_present, nicht diesen Zähler.
