UPDATE fields x SET description = 'Risiko-Maßnahmenplan je Risiko (Technische/Organisatorische/Personelle Maßnahmen) nach DWA-M 820-1 Anhang A Tab. A.2, auf die §4.8.2 verweist. Nicht verpflichtend.
[EN] Risk mitigation plan per risk (technical/organisational/personnel measures) following DWA-M 820-1 Annex A Table A.2, referenced by §4.8.2. Not required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-10' AND x.symbol = 'risk_mitigation_plan';
