UPDATE compliance_requirements x SET description = 'Blockiert, bis framework_conditions_clarified bestätigt ist. §5.2.2: umfassende Bedarfsplanung nach DWA-M 820-1, Förderfähigkeit und Voraussetzungen geklärt.
