UPDATE compliance_requirements x SET description = 'Blockiert, bis forward_planning_done bestätigt ist. §5.2.3: periodische Beurteilung des Anlagenbestands statt kurzfristiger Reaktion vor Ablauf der Nutzungsdauer.
