UPDATE fields x SET description = 'Bestätigt, dass alle Projektentscheidungen transparent dokumentiert sind. §5.3.2: "Entscheidungen müssen, einschließlich der Gründe, transparent und nachvollziehbar dokumentiert sein und dauerhaft Bestand haben."
