UPDATE fields x SET description = 'Bestätigt, dass der Planungszeitraum realistisch zur Projektkomplexität passt. §5.3.4: Auftragnehmer fordern rechtzeitig ausreichend Zeit ein; "Die Auftragnehmer müssen zur Verfügung gestellte Zeit auch nutzen."
[EN] Confirms the planning period realistically matches the project''s complexity. §5.3.4: contractors request sufficient time in good time; "contractors must also make use of the time made available."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-12' AND x.symbol = 'planning_duration_realistic';
UPDATE fields x SET description = 'Tabellarische Entscheidungsdokumentation (§5.3.1): eine Zeile je Entscheidung mit Datum, Entscheidung, Begründung, Verantwortlich; Entscheidung und Begründung ausfüllen - leere Begründungen werden gezählt. §5.3.2: Entscheidungen müssen einschließlich der Gründe dokumentiert sein.
[EN] Tabular decision log (§5.3.1): one row per decision with date, decision, rationale, responsible; fill decision and rationale - empty rationales are counted. §5.3.2: decisions must be documented including the reasons.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-12' AND x.symbol = 'entscheidungen';
UPDATE fields x SET description = 'Zählt die Zeilen des Entscheidungs-Registers. Rein informativ.
