UPDATE compliance_requirements x SET description = 'Blockiert, bis meeting_protocols_active bestätigt ist. §5.3.1: Kommunikation muss regelmäßig, vorbereitet, effektiv und dokumentiert sein - keine unvorbereiteten Ad-hoc-Besprechungen.
[EN] Blocks until meeting_protocols_active is confirmed. §5.3.1: communication must be regular, prepared, effective and documented - no unprepared ad-hoc meetings.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-12' AND x.code = 'REQ-24';
UPDATE compliance_requirements x SET description = 'Blockiert, bis decisions_documented bestätigt ist. §5.3.2: Entscheidungen müssen einschließlich der Gründe transparent und nachvollziehbar dokumentiert sein.
