UPDATE compliance_requirements x SET description = 'Blockiert, bis third_parties_engaged_early bestätigt ist. §5.3.5: Dritte sind möglichst frühzeitig einzubinden und, falls erforderlich, frühzeitig zu beauftragen.
[EN] Blocks until third_parties_engaged_early is confirmed. §5.3.5: third parties are to be brought in as early as possible and, if necessary, commissioned early.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-13' AND x.code = 'REQ-28';
