UPDATE fields x SET description = 'Mehrfachauswahl der abgeschlossenen Leistungsphasen LPH 0-9. §1 definiert diese Phasenspanne; §4.6.2 regelt die Freigabe nach jeder abgeschlossenen Phase.
[EN] Multi-select of the completed HOAI phases LPH 0-9. §1 defines this phase span; §4.6.2 regulates the release after each completed phase.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-15' AND x.symbol = 'lph_completed';
UPDATE fields x SET description = 'Bestätigt, dass die im Rahmenterminplan festgelegten Planungs-Meilensteine erreicht wurden. §4.4.1 definiert den Rahmenterminplan als Träger der wesentlichen Meilensteine.
