UPDATE compliance_requirements x SET description = 'Blockiert, bis training_complete bestätigt ist. §5.7.5: Einweisungen des Betriebspersonals erfolgen in ausreichender Tiefe für einen optimalen, sicheren Betrieb.
[EN] Blocks until training_complete is confirmed. §5.7.5: training of the operating personnel is carried out in sufficient depth for optimal, safe operation.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-23' AND x.code = 'REQ-49';
UPDATE fields x SET description = 'Bestätigt aktive Mängelverfolgung während der Gewährleistungsfrist. §5.8.3 (Ziel): "Eine konsequente Verfolgung der Gewährleistungszeit, insbesondere die Mängelverfolgung der erbrachten Werkleistungen, ist ein wichtiges Element zu einem kostengünstigen Betrieb." Nur sichtbar, solange LPH 9 stattfindet.
[EN] Confirms active defect tracking during the warranty period. §5.8.3 (target state): "consistent tracking of the warranty period, in particular tracking of defects in the work performed, is a key element for cost-effective plant operation." Only shown while LPH 9 takes place.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.symbol = 'defect_tracking_active';
UPDATE fields x SET description = 'Ende der Gewährleistungsfrist (bei mehreren Firmen das späteste; Einzelwerte je Firma im Gewährleistungskalender). §5.8.2: "Das Ende der Gewährleistungszeit wird jeweils durch ein Datum benannt." Nur sichtbar, solange LPH 9 stattfindet.
[EN] End of the warranty period (for several firms the latest; per-firm dates in the warranty calendar). §5.8.2: "the end of the warranty period is in each case named by a date." Only shown while LPH 9 takes place.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.symbol = 'warranty_end_date';
UPDATE fields x SET description = 'Beginn der Gewährleistungsfrist (bei mehreren Firmen der früheste; Einzelwerte je Firma im Gewährleistungskalender). §5.8.2 (Ziel): Es gibt einen eindeutigen Abnahmezeitpunkt für jeden Auftragnehmer. Nur sichtbar, solange LPH 9 stattfindet.
[EN] Start of the warranty period (for several firms the earliest; per-firm dates in the warranty calendar). §5.8.2 (target state): there is a clear acceptance date for each contractor. Only shown while LPH 9 takes place.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.symbol = 'warranty_start_date';
UPDATE fields x SET description = 'Gewährleistungskalender je Auftragnehmer/ausführender Firma (Abnahme, Beginn, Ende, offene Mängel). §5.8.2: je Auftragnehmer ein eindeutiger Abnahmezeitpunkt und ein benanntes Fristende; §5.8.3: konsequente Mängelverfolgung.
[EN] Warranty calendar per contractor/executing firm (acceptance, start, end, open defects). §5.8.2: a clear acceptance point and a named end date per contractor; §5.8.3: consistent defect tracking.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.symbol = 'gewaehrleistungen';
UPDATE fields x SET description = 'Zählt die Zeilen des Gewährleistungskalenders. Rein informativ - REQ-51 liest weiterhin die Einzelfelder warranty_start_date/warranty_end_date.
[EN] Counts the rows of the warranty calendar. Informational only - REQ-51 still reads the individual warranty_start_date/warranty_end_date fields.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.symbol = 'warranty_count';
UPDATE fields x SET description = 'Summiert das Feld maengel_offen über alle Zeilen des Gewährleistungskalenders, wobei leere Zellen als 0 gezählt werden. Kein Gate.
[EN] Sums the maengel_offen field across all warranty-calendar rows, treating blank cells as 0. No gate reads it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.symbol = 'warranty_open_defects';
UPDATE fields x SET description = 'Name/Funktion der für LPH 9 verantwortlichen Stelle. §5.8.3: "Es ist festgelegt, wer für die Phase LPH 9 verantwortlich ist." Nur sichtbar, solange LPH 9 stattfindet (820-2-01).
[EN] Name/role of the party responsible for phase LPH 9. §5.8.3: "it is laid down who is responsible for phase LPH 9." Only shown while LPH 9 takes place (820-2-01).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.symbol = 'verantwortlich_lph9_name';
UPDATE equations x SET description = 'Zählt die Zeilen des Gewährleistungskalenders gewaehrleistungen.
[EN] Counts the rows of the gewaehrleistungen warranty calendar.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.equation_number = '820-2-24-D1';
UPDATE equations x SET description = 'Summiert das Feld maengel_offen über alle Zeilen des Gewährleistungskalenders, leere Zellen als 0.
[EN] Sums the maengel_offen field across all warranty-calendar rows, blank cells as 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.equation_number = '820-2-24-D2';
UPDATE compliance_requirements x SET description = 'Blockiert, bis warranty_start_date UND warranty_end_date gesetzt sind - solange LPH 9 stattfindet (820-2-01: verantwortung_lph9 != entfällt). §5.8.2: ein eindeutiger Abnahmezeitpunkt und ein benanntes Fristende je Auftragnehmer.
[EN] Blocks until BOTH warranty_start_date and warranty_end_date are set - whenever LPH 9 takes place (820-2-01: verantwortung_lph9 != does-not-occur). §5.8.2: a clear acceptance point and a named end date per contractor.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.code = 'REQ-51';
UPDATE compliance_requirements x SET description = 'Blockiert, bis defect_tracking_active bestätigt ist - solange LPH 9 stattfindet. §5.8.3: konsequente Mängelverfolgung während der Gewährleistungsfrist ist Element eines kostengünstigen Betriebs.
[EN] Blocks until defect_tracking_active is confirmed - whenever LPH 9 takes place. §5.8.3: consistent defect tracking during the warranty period is an element of cost-effective operation.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.code = 'REQ-52';
UPDATE compliance_requirements x SET description = 'Blockiert, bis verantwortlich_lph9_name gesetzt ist - solange LPH 9 stattfindet (820-2-01). §5.8.3: "Es ist festgelegt, wer für die Phase LPH 9 verantwortlich ist."
[EN] Blocks until verantwortlich_lph9_name is set - whenever LPH 9 takes place (820-2-01). §5.8.3: "it is laid down who is responsible for phase LPH 9."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-24' AND x.code = 'REQ-52-2';
UPDATE fields x SET description = 'Bestätigt, dass ein Freigabe-/Fortschreibungsprozess für Regelwerke existiert. §6.3.3 (Ziel): "Es gibt gut funktionierende Prozesse zur Aktualisierung von Richtlinien und Regelwerken."
[EN] Confirms an approval/update process for Regelwerke exists. §6.3.3 (target state): "there are well-functioning processes for updating guidelines and Regelwerke."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-25' AND x.symbol = 'approval_release_process';
UPDATE fields x SET description = 'Freitext zu Zeitplan/Prozess der Regelwerk-Fortschreibung. §6.3.1: die Regelwerke müssen stets auf dem neuesten Stand sein; §6.3.2: die vorhandenen, auf das notwendige Maß reduzierten Regelwerke sind vollständig anzuwenden.
[EN] Free text on the schedule/process for updating client guidelines. §6.3.1: the Regelwerke must always be up to date; §6.3.2: the existing, reduced-to-necessary Regelwerke are to be applied in full.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-25' AND x.symbol = 'guidelines_update_schedule';
UPDATE compliance_requirements x SET description = 'Blockiert, bis approval_release_process bestätigt ist. §6.3.3: ein funktionierender Fortschreibungs- und Freigabeprozess für Regelwerke besteht.
[EN] Blocks until approval_release_process is confirmed. §6.3.3: a working update and release process for Regelwerke exists.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-25' AND x.code = 'REQ-54';
UPDATE fields x SET description = 'Bestätigt, dass Innovationsspielraum und Regeln für Auftraggeber und Auftragnehmer definiert sind. §7.3/§7.4 beschreiben die Rolle beider Seiten beim Umgang mit innovativen Lösungsansätzen. Nicht verpflichtend, kein Gate liest dieses Feld.
[EN] Confirms the scope for innovation and the rules for client and contractor are defined. §7.3/§7.4 describe both sides'' role in handling innovative approaches. Not required, no gate reads this field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-26' AND x.symbol = 'innovation_scope_defined';
UPDATE fields x SET description = 'Bestätigt, dass Ideenschutz, Vergütung und Nutzungsrechte für innovative Lösungen geregelt sind. §7.6.2 (Ziel): "Es werden klare Vereinbarungen über Ideen und Innovationen geschaffen, um einen Anreiz zu geben, neue Ideen zu entwickeln."
[EN] Confirms idea protection, compensation and usage rights for innovative solutions are regulated. §7.6.2 (target state): "clear agreements on ideas and innovations are created, to give an incentive to develop new ideas."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-26' AND x.symbol = 'ip_rights_defined';
UPDATE fields x SET description = 'Bestätigt, dass Haftungsfragen bei innovativen Lösungen vertraglich geregelt sind. §7.5: "Die Haftungsfragen, die sich insbesondere mit neuartigen, innovativen Lösungsansätzen ergeben, die nicht die anerkannten Regeln der Technik erfüllen, sind vertraglich fair verteilt."
[EN] Confirms liability questions for innovative solutions are contractually regulated. §7.5: "liability questions arising in particular from novel, innovative approaches that do not meet the generally accepted rules of technology are fairly distributed by contract."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-26' AND x.symbol = 'liability_clarified';
UPDATE compliance_requirements x SET description = 'Warnt (unverbindlich), solange liability_clarified nicht bestätigt ist. §7.5 (Zielbild): Die Haftungsfragen bei neuartigen, innovativen Lösungsansätzen, die nicht die anerkannten Regeln der Technik erfüllen, sind vertraglich fair verteilt.
[EN] Warns (non-blocking) while liability_clarified is not confirmed. §7.5 (target state): liability questions arising from novel, innovative approaches that do not meet the accepted rules of technology are fairly distributed by contract.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-26' AND x.code = 'REQ-55';
UPDATE compliance_requirements x SET description = 'Blockiert, bis ip_rights_defined bestätigt ist. §7.6.2: klare Vereinbarungen über Ideenschutz und Nutzungsrechte schaffen einen Anreiz für neue Ideen.
[EN] Blocks until ip_rights_defined is confirmed. §7.6.2: clear agreements on idea protection and usage rights create an incentive for new ideas.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-26' AND x.code = 'REQ-56';
UPDATE fields x SET description = 'Bestätigt, dass BIM-Grundlagen (z.B. AIA) vorliegen. §8.3.2 (Vorschlag): "Es wird geklärt, ob das Projekt für die Anwendung der BIM-Methodik geeignet ist und ob die Beteiligten ... die nötigen Kompetenzen und Qualifikationen aufweisen." Nur relevant, wenn mit BIM gearbeitet wird.
[EN] Confirms BIM foundations (e.g. AIA) are in place. §8.3.2 (suggestion): "it is clarified whether the project suits the BIM method and whether the parties ... have the necessary competences and qualifications." Only relevant when the project runs with BIM.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.symbol = 'bim_basics_established';
UPDATE fields x SET description = 'Freitext zur gemeinsamen Datenplattform (CDE). §8.3.3 (Ziel): eine stets aktuelle Datenplattform mit konsequenter Administration erleichtert das Datenmanagement.
[EN] Free text naming the common data environment (CDE). §8.3.3 (target state): a constantly current data platform with consistent administration eases data management.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.symbol = 'data_platform_defined';
UPDATE fields x SET description = 'Bestätigt, dass die Datenqualität (Vollständigkeit, Eindeutigkeit, Korrektheit, Aktualität, Genauigkeit nach §2.1) geprüft wurde. §8.2.2: "Die Qualität der vom Auftraggeber bereitgestellten Daten muss vor der Ausschreibung von Planungsleistungen bekannt sein."
[EN] Confirms data quality (completeness, uniqueness, correctness, currency, accuracy per §2.1) was checked. §8.2.2: "the quality of the data provided by the client must be known before planning services are put out to tender."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.symbol = 'data_quality_checked';
UPDATE fields x SET description = 'Register der eingesetzten Software mit Einsatzzweck. §8.2.1: client-seitige Softwarevorgaben "sollten nur in Einzelfällen formuliert werden"; wo vorhanden, "müssen sie in der Angebotsanfrage transparent gemacht werden".
[EN] Register of software products in use with their purpose. §8.2.1: client-side software requirements "should only be formulated in individual cases"; where they exist, "they must be made transparent in the request for proposals".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.symbol = 'software_products_defined';
UPDATE fields x SET description = 'Bestätigung, ob das Projekt mit der BIM-Methode abgewickelt wird. Steuert, ob bim_basics_established und REQ-59 geprüft werden.
[EN] Confirms whether the project is run with the BIM method. Gates whether bim_basics_established and REQ-59 are checked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.symbol = 'bim_methode_angewendet';
UPDATE compliance_requirements x SET description = 'Warnt (unverbindlich), solange das Software-Register (software_products_defined) leer ist. §8.2.1: Softwarevorgaben des Auftraggebers sollten nur in Einzelfällen formuliert werden und müssen in der Angebotsanfrage transparent gemacht werden.
[EN] Warns (non-blocking) while the software register is empty. §8.2.1: client software requirements should only be set in individual cases and must be made transparent in the request for proposals.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.code = 'REQ-57';
UPDATE compliance_requirements x SET description = 'Blockiert, bis data_quality_checked bestätigt ist. §8.2.2: "Die Qualität der vom Auftraggeber bereitgestellten Daten muss vor der Ausschreibung von Planungsleistungen bekannt sein"; §2.1 benennt die Kriterien Vollständigkeit, Eindeutigkeit, Korrektheit, Aktualität, Genauigkeit.
[EN] Blocks until data_quality_checked is confirmed. §8.2.2: "the quality of the data provided by the client must be known before planning services are put out to tender"; §2.1 names the criteria completeness, uniqueness, correctness, currency, accuracy.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.code = 'REQ-58';
UPDATE compliance_requirements x SET description = 'Warnt, bis bim_basics_established bestätigt ist - nur wenn bim_methode_angewendet mit "ja" beantwortet ist. §8.3.2: es wird geklärt, ob das Projekt für BIM geeignet ist und die nötigen Kompetenzen vorhanden sind.
[EN] Warns until bim_basics_established is confirmed - only when bim_methode_angewendet is answered "yes". §8.3.2: it is clarified whether the project suits BIM and the necessary competences are in place.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-27' AND x.code = 'REQ-59';
UPDATE fields x SET description = 'Register technischer/organisatorischer Maßnahmen (TOM) zur Datensicherheit. §8.8 nennt u.a. Zugriffsrechte, Bandbreiten, Lebensdauer/Versionierung und Dokumentation der Zugriffsrechte als Aspekte, die Berücksichtigung finden sollten.
[EN] Register of technical/organisational measures (TOM) for data security. §8.8 names access rights, bandwidth, lifecycle/versioning and documentation of access rights among the aspects that should be considered.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-28' AND x.symbol = 'data_security_measures';
UPDATE fields x SET description = 'Bestätigt, dass Rechte an digitalen Daten/Modellen geklärt sind. §8.9: "der Auftraggeber darf die Daten für das Projekt verwenden ..., nicht aber für andere Projekte, wenn er sich diese Rechte nicht ausdrücklich und gegen Vergütung hat einräumen lassen."
[EN] Confirms rights to digital data/models are clarified. §8.9: the client may use the data for the project, but not for other projects unless these rights have been expressly granted to him against payment.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-28' AND x.symbol = 'digital_rights_clarified';
UPDATE fields x SET description = 'Einschätzung der Qualität verwendeter GIS-Daten. §8.7 (Ziel): "Die Qualität von in Geoinformationssystemen verarbeiteten Daten ist in Metadaten dokumentiert. Angaben zu Herkunft, Aktualität und Genauigkeit sind vorhanden."
[EN] Assessment of the quality of GIS data used. §8.7 (target state): "the quality of data processed in geoinformation systems is documented in metadata. Information on origin, currency and accuracy is available."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-28' AND x.symbol = 'gis_data_quality';
UPDATE compliance_requirements x SET description = 'Warnt, solange data_security_measures leer ODER digital_rights_clarified nicht bestätigt ist. §8.8: technische/organisatorische Maßnahmen (TOM) nach DSGVO/BSI; §8.9: Rechte an digitalen Daten sind geklärt.
[EN] Warns while data_security_measures is empty OR digital_rights_clarified is not confirmed. §8.8: technical/organisational measures (TOM) per DSGVO/BSI; §8.9: rights to digital data are clarified.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-2' AND w.code = '820-2-28' AND x.code = 'REQ-60';
COMMIT;
